  'medium',
  'es',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"¿Qué festival de cine, celebrado en el Lido, es el más antiguo del mundo?","options":[{"id":"a","text":"Cannes","is_correct":false},{"id":"b","text":"Venecia","is_correct":true},{"id":"c","text":"Berlín","is_correct":false},{"id":"d","text":"Sundance","is_correct":false}],"explanation":"El Festival de Cine de Venecia se fundó en 1932 y es el festival de cine más antiguo del mundo."},{"id":"q2","question":"¿En qué año se celebró por primera vez el Festival de Cannes?","options":[{"id":"a","text":"1939","is_correct":false},{"id":"b","text":"1946","is_correct":true},{"id":"c","text":"1951","is_correct":false},{"id":"d","text":"1955","is_correct":false}],"explanation":"Se planeó una primera edición para 1939, pero estalló la guerra; el festival abrió por fin en 1946."},{"id":"q3","question":"¿Cómo se llama el premio máximo del Festival de Cannes?","options":[{"id":"a","text":"León de Oro","is_correct":false},{"id":"b","text":"Oso de Oro","is_correct":false},{"id":"c","text":"Palma de Oro","is_correct":true},{"id":"d","text":"Concha de Oro","is_correct":false}],"explanation":"La Palma de Oro es el premio máximo de Cannes desde 1955."},{"id":"q4","question":"El León de Oro es el premio máximo de qué festival?","options":[{"id":"a","text":"Venecia","is_correct":true},{"id":"b","text":"Berlín","is_correct":false},{"id":"c","text":"Locarno","is_correct":false},{"id":"d","text":"Cannes","is_correct":false}],"explanation":"El León de Oro corona a la mejor película de Venecia desde 1949."},{"id":"q5","question":"¿En qué año se fundó el Festival Internacional de Cine de Berlín, la Berlinale?","options":[{"id":"a","text":"1946","is_correct":false},{"id":"b","text":"1951","is_correct":true},{"id":"c","text":"1959","is_correct":false},{"id":"d","text":"1968","is_correct":false}],"explanation":"La Berlinale nació en 1951, en plena Guerra Fría, como escaparate del cine mundial."},{"id":"q6","question":"¿Qué premio entrega la Berlinale a su mejor película?","options":[{"id":"a","text":"Palma de Oro","is_correct":false},{"id":"b","text":"Concha de Oro","is_correct":false},{"id":"c","text":"Cámara de Oro","is_correct":false},{"id":"d","text":"Oso de Oro","is_correct":true}],"explanation":"El Oso de Oro alude al oso del escudo de Berlín."},{"id":"q7","question":"¿Qué festival español, fundado en 1953, entrega la Concha de Oro?","options":[{"id":"a","text":"San Sebastián","is_correct":true},{"id":"b","text":"Málaga","is_correct":false},{"id":"c","text":"Valladolid","is_correct":false},{"id":"d","text":"Sitges","is_correct":false}],"explanation":"El Festival de San Sebastián debe su Concha de Oro a la bahía de La Concha."},{"id":"q8","question":"¿En qué famoso bulevar se celebra el Festival de Cannes?","options":[{"id":"a","text":"Campos Elíseos","is_correct":false},{"id":"b","text":"Vía Veneto","is_correct":false},{"id":"c","text":"La Croisette","is_correct":true},{"id":"d","text":"Hollywood Boulevard","is_correct":false}],"explanation":"El Palacio de Festivales está sobre La Croisette, el bulevar junto al mar de Cannes."}]'::jsonb,
