  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"In which year was the first Grammy Awards ceremony held?","options":[{"id":"a","text":"1949","is_correct":false},{"id":"b","text":"1959","is_correct":true},{"id":"c","text":"1965","is_correct":false},{"id":"d","text":"1973","is_correct":false}],"explanation":"The first Grammys were presented on 4 May 1959, honouring music released in 1958."},{"id":"q2","question":"The Grammy trophy depicts which object?","options":[{"id":"a","text":"A microphone","is_correct":false},{"id":"b","text":"A gramophone","is_correct":true},{"id":"c","text":"A vinyl record","is_correct":false},{"id":"d","text":"A treble clef","is_correct":false}],"explanation":"The gilded gramophone is what gives the Grammy its name."},{"id":"q3","question":"Which organization presents the Grammy Awards?","options":[{"id":"a","text":"The Recording Academy","is_correct":true},{"id":"b","text":"The Academy of Motion Picture Arts and Sciences","is_correct":false},{"id":"c","text":"The American Music Association","is_correct":false},{"id":"d","text":"The Hollywood Foreign Press Association","is_correct":false}],"explanation":"The Recording Academy, founded in 1957, votes on and presents the Grammys."},{"id":"q4","question":"In which year was the first Latin Grammy Awards ceremony held?","options":[{"id":"a","text":"1995","is_correct":false},{"id":"b","text":"1998","is_correct":false},{"id":"c","text":"2000","is_correct":true},{"id":"d","text":"2005","is_correct":false}],"explanation":"The Latin Recording Academy held the first Latin Grammy ceremony in 2000."},{"id":"q5","question":"Which Italian singer won the very first Grammy for Record of the Year, with «Nel Blu Dipinto Di Blu (Volare)»?","options":[{"id":"a","text":"Frank Sinatra","is_correct":false},{"id":"b","text":"Domenico Modugno","is_correct":true},{"id":"c","text":"Dean Martin","is_correct":false},{"id":"d","text":"Perry Como","is_correct":false}],"explanation":"Modugno''s «Volare» won both Record of the Year and Song of the Year at the first Grammys."},{"id":"q6","question":"Album of the Year, Record of the Year, Song of the Year and which other award form the Grammys'' Big Four?","options":[{"id":"a","text":"Best New Artist","is_correct":true},{"id":"b","text":"Best Pop Vocal Album","is_correct":false},{"id":"c","text":"Producer of the Year","is_correct":false},{"id":"d","text":"Best Music Video","is_correct":false}],"explanation":"The four general-field categories, open to every genre, are known as the Big Four."},{"id":"q7","question":"Who won the first Grammy for Album of the Year, for «The Music from Peter Gunn»?","options":[{"id":"a","text":"Henry Mancini","is_correct":true},{"id":"b","text":"Frank Sinatra","is_correct":false},{"id":"c","text":"Ella Fitzgerald","is_correct":false},{"id":"d","text":"Nat King Cole","is_correct":false}],"explanation":"Mancini''s soundtrack to the TV series Peter Gunn took the first Album of the Year."},{"id":"q8","question":"Who was the first winner of the Grammy for Best New Artist?","options":[{"id":"a","text":"Bobby Darin","is_correct":true},{"id":"b","text":"Elvis Presley","is_correct":false},{"id":"c","text":"Sam Cooke","is_correct":false},{"id":"d","text":"Connie Francis","is_correct":false}],"explanation":"Darin took the first Best New Artist award at the second Grammy ceremony, the same night «Mack the Knife» won Record of the Year."}]'::jsonb,
