  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"In which year were the first Emmy Awards presented?","options":[{"id":"a","text":"1949","is_correct":true},{"id":"b","text":"1955","is_correct":false},{"id":"c","text":"1961","is_correct":false},{"id":"d","text":"1968","is_correct":false}],"explanation":"The first Emmys were handed out on 25 January 1949 at the Hollywood Athletic Club."},{"id":"q2","question":"The Emmy statuette depicts a winged woman holding which object?","options":[{"id":"a","text":"A globe","is_correct":false},{"id":"b","text":"A star","is_correct":false},{"id":"c","text":"An atom","is_correct":true},{"id":"d","text":"A lightning bolt","is_correct":false}],"explanation":"The winged muse holds an atom, symbolising the arts and sciences of television."},{"id":"q3","question":"The name «Emmy» comes from «Immy», a nickname for which piece of TV technology?","options":[{"id":"a","text":"The cathode ray tube","is_correct":false},{"id":"b","text":"The image orthicon camera tube","is_correct":true},{"id":"c","text":"The satellite dish","is_correct":false},{"id":"d","text":"The kinescope","is_correct":false}],"explanation":"«Immy» was slang for the image orthicon tube used in early television cameras."},{"id":"q4","question":"Who received the very first Emmy Award in 1949?","options":[{"id":"a","text":"Milton Berle","is_correct":false},{"id":"b","text":"Lucille Ball","is_correct":false},{"id":"c","text":"Shirley Dinsdale","is_correct":true},{"id":"d","text":"Ed Sullivan","is_correct":false}],"explanation":"Ventriloquist Shirley Dinsdale was named Most Outstanding Television Personality."},{"id":"q5","question":"Which Emmy ceremony honours daytime programming like soap operas and talk shows?","options":[{"id":"a","text":"The Daytime Emmy Awards","is_correct":true},{"id":"b","text":"The Primetime Emmy Awards","is_correct":false},{"id":"c","text":"The Creative Arts Emmys","is_correct":false},{"id":"d","text":"The International Emmy Awards","is_correct":false}],"explanation":"The Daytime Emmys have celebrated daytime television since 1974."},{"id":"q6","question":"In which year were the International Emmy Awards founded?","options":[{"id":"a","text":"1959","is_correct":false},{"id":"b","text":"1965","is_correct":false},{"id":"c","text":"1973","is_correct":true},{"id":"d","text":"1981","is_correct":false}],"explanation":"The International Academy created the International Emmys in 1973 for television produced outside the United States."},{"id":"q7","question":"Which academy administers the Primetime Emmy Awards?","options":[{"id":"a","text":"The Academy of Television Arts & Sciences","is_correct":true},{"id":"b","text":"The National Academy of Television Arts & Sciences","is_correct":false},{"id":"c","text":"The Academy of Motion Picture Arts and Sciences","is_correct":false},{"id":"d","text":"The International Academy of Television Arts & Sciences","is_correct":false}],"explanation":"The Television Academy (ATAS), based in Los Angeles, runs the Primetime Emmys; NATAS handles the Daytime Emmys."},{"id":"q8","question":"The flagship Emmy honour for a drama is called Outstanding what?","options":[{"id":"a","text":"Drama Series","is_correct":true},{"id":"b","text":"Dramatic Production","is_correct":false},{"id":"c","text":"Television Drama","is_correct":false},{"id":"d","text":"Drama Program","is_correct":false}],"explanation":"Outstanding Drama Series is the flagship Emmy category for scripted drama."}]'::jsonb,
