insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-award-show-moments-trivia',
  'Award Show Moments Trivia: The Nights Everyone Remembers',
  'Eight questions on historic award-show moments: famous firsts, declined trophies and the envelope mix-up everyone still talks about.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"In which year was the first Academy Awards ceremony held?","options":[{"id":"a","text":"1929","is_correct":true},{"id":"b","text":"1935","is_correct":false},{"id":"c","text":"1941","is_correct":false},{"id":"d","text":"1948","is_correct":false}],"explanation":"The first Oscars were a private dinner at the Hollywood Roosevelt Hotel on 16 May 1929."},{"id":"q2","question":"Who became the first African American performer to win an Oscar, for Gone with the Wind in 1940?","options":[{"id":"a","text":"Hattie McDaniel","is_correct":true},{"id":"b","text":"Butterfly McQueen","is_correct":false},{"id":"c","text":"Lena Horne","is_correct":false},{"id":"d","text":"Ethel Waters","is_correct":false}],"explanation":"McDaniel won Best Supporting Actress for playing Mammy in Gone with the Wind."},{"id":"q3","question":"In 2010, who became the first woman to win the Oscar for Best Director?","options":[{"id":"a","text":"Sofia Coppola","is_correct":false},{"id":"b","text":"Kathryn Bigelow","is_correct":true},{"id":"c","text":"Jane Campion","is_correct":false},{"id":"d","text":"Chloé Zhao","is_correct":false}],"explanation":"Bigelow won for The Hurt Locker at the 82nd Academy Awards."},{"id":"q4","question":"At the 2017 Oscars, which film was mistakenly announced as Best Picture before Moonlight was named the real winner?","options":[{"id":"a","text":"La La Land","is_correct":true},{"id":"b","text":"Arrival","is_correct":false},{"id":"c","text":"Manchester by the Sea","is_correct":false},{"id":"d","text":"Fences","is_correct":false}],"explanation":"The presenters were handed the wrong envelope and read out La La Land before the error was corrected on stage."},{"id":"q5","question":"In 1973, which actor declined his Best Actor Oscar for The Godfather?","options":[{"id":"a","text":"Al Pacino","is_correct":false},{"id":"b","text":"Marlon Brando","is_correct":true},{"id":"c","text":"James Caan","is_correct":false},{"id":"d","text":"Jack Nicholson","is_correct":false}],"explanation":"Brando refused the award and sent activist Sacheen Littlefeather to speak in his place."},{"id":"q6","question":"Who was the first Black actor to win the Oscar for Best Actor, in 1964?","options":[{"id":"a","text":"Sidney Poitier","is_correct":true},{"id":"b","text":"Harry Belafonte","is_correct":false},{"id":"c","text":"James Earl Jones","is_correct":false},{"id":"d","text":"Ossie Davis","is_correct":false}],"explanation":"Poitier won for Lilies of the Field at the 36th Academy Awards."},{"id":"q7","question":"In 2020, which film became the first non-English-language movie to win the Oscar for Best Picture?","options":[{"id":"a","text":"Roma","is_correct":false},{"id":"b","text":"Parasite","is_correct":true},{"id":"c","text":"Amour","is_correct":false},{"id":"d","text":"Life Is Beautiful","is_correct":false}],"explanation":"Bong Joon-ho''s Parasite won four Oscars, including Best Picture, at the 92nd ceremony."},{"id":"q8","question":"In 2002, who became the first Black woman to win the Oscar for Best Actress?","options":[{"id":"a","text":"Whoopi Goldberg","is_correct":false},{"id":"b","text":"Halle Berry","is_correct":true},{"id":"c","text":"Angela Bassett","is_correct":false},{"id":"d","text":"Viola Davis","is_correct":false}],"explanation":"Berry won for Monster''s Ball at the 74th Academy Awards."}]'::jsonb,
  null,
  array['award shows', 'trivia', 'oscars', 'history', 'pop culture']::text[],
  3,
  'published',
  false,
  false,
  now()
)
