  'es',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"¿En qué año se celebró la primera ceremonia de los premios Óscar?","options":[{"id":"a","text":"1929","is_correct":true},{"id":"b","text":"1935","is_correct":false},{"id":"c","text":"1941","is_correct":false},{"id":"d","text":"1948","is_correct":false}],"explanation":"Los primeros Óscar fueron una cena privada en el hotel Hollywood Roosevelt el 16 de mayo de 1929."},{"id":"q2","question":"¿Quién fue la primera artista afroamericana en ganar un Óscar, por Lo que el viento se llevó en 1940?","options":[{"id":"a","text":"Hattie McDaniel","is_correct":true},{"id":"b","text":"Butterfly McQueen","is_correct":false},{"id":"c","text":"Lena Horne","is_correct":false},{"id":"d","text":"Ethel Waters","is_correct":false}],"explanation":"McDaniel ganó el premio a Mejor Actriz de Reparto por su papel de Mammy en Lo que el viento se llevó."},{"id":"q3","question":"En 2010, ¿quién fue la primera mujer en ganar el Óscar a Mejor Dirección?","options":[{"id":"a","text":"Sofia Coppola","is_correct":false},{"id":"b","text":"Kathryn Bigelow","is_correct":true},{"id":"c","text":"Jane Campion","is_correct":false},{"id":"d","text":"Chloé Zhao","is_correct":false}],"explanation":"Bigelow ganó por «The Hurt Locker» en la 82.ª ceremonia."},{"id":"q4","question":"En los Óscar de 2017, ¿qué película se anunció por error como Mejor Película antes de que Moonlight fuera declarada ganadora?","options":[{"id":"a","text":"La La Land","is_correct":true},{"id":"b","text":"La llegada","is_correct":false},{"id":"c","text":"Manchester junto al mar","is_correct":false},{"id":"d","text":"Fences","is_correct":false}],"explanation":"Los presentadores recibieron el sobre equivocado y leyeron La La Land antes de corregir el error en el escenario."},{"id":"q5","question":"En 1973, ¿qué actor rechazó su Óscar a Mejor Actor por El padrino?","options":[{"id":"a","text":"Al Pacino","is_correct":false},{"id":"b","text":"Marlon Brando","is_correct":true},{"id":"c","text":"James Caan","is_correct":false},{"id":"d","text":"Jack Nicholson","is_correct":false}],"explanation":"Brando rechazó el premio y envió a la activista Sacheen Littlefeather a hablar en su lugar."},{"id":"q6","question":"¿Quién fue el primer actor negro en ganar el Óscar a Mejor Actor, en 1964?","options":[{"id":"a","text":"Sidney Poitier","is_correct":true},{"id":"b","text":"Harry Belafonte","is_correct":false},{"id":"c","text":"James Earl Jones","is_correct":false},{"id":"d","text":"Ossie Davis","is_correct":false}],"explanation":"Poitier ganó por «Lilies of the Field» en la 36.ª ceremonia."},{"id":"q7","question":"En 2020, ¿qué película fue la primera en idioma no inglés en ganar el Óscar a Mejor Película?","options":[{"id":"a","text":"Roma","is_correct":false},{"id":"b","text":"Parásitos","is_correct":true},{"id":"c","text":"Amour","is_correct":false},{"id":"d","text":"La vida es bella","is_correct":false}],"explanation":"«Parásitos», de Bong Joon-ho, ganó cuatro Óscar, incluido el de Mejor Película, en la 92.ª ceremonia."},{"id":"q8","question":"En 2002, ¿quién fue la primera mujer negra en ganar el Óscar a Mejor Actriz?","options":[{"id":"a","text":"Whoopi Goldberg","is_correct":false},{"id":"b","text":"Halle Berry","is_correct":true},{"id":"c","text":"Angela Bassett","is_correct":false},{"id":"d","text":"Viola Davis","is_correct":false}],"explanation":"Berry ganó por «Monster''s Ball» en la 74.ª ceremonia."}]'::jsonb,
